'use strict';

const { spawnSync } = require('node:child_process');
const fs = require('node:fs');
const path = require('node:path');

const packageRoot = path.resolve(__dirname, '..');
const host = path.join(packageRoot, 'bridge', 'transform-host.js');
const executable = process.env.JSCODESHIFT_RUST_BINARY || path.join(
  packageRoot,
  'rust',
  'target',
  'release',
  process.platform === 'win32' ? 'jscodeshift-rs.exe' : 'jscodeshift-rs'
);

if (fs.existsSync(executable)) {
  const result = spawnSync(executable, process.argv.slice(2), {
    cwd: process.cwd(),
    env: {...process.env, JSCODESHIFT_BRIDGE: host},
    stdio: 'inherit',
  });

  if (result.error) {
    throw result.error;
  }
  process.exitCode = result.status === null ? 1 : result.status;
} else {
  // Source checkouts remain usable before the Rust launcher has been built.
  require(host);
}
